const dayInMilliseconds=864e5;function updateBlogUptime(){for(const s of document.querySelectorAll("[data-blog-since]")){const[n,o,c]=s.dataset.blogSince.split("-").map(Number),t=new Date,i=Date.UTC(t.getFullYear(),t.getMonth(),t.getDate());let e=Math.max(0,(t.getFullYear()-n)*12+t.getMonth()-o+1);const a=e=>{const t=o-1+e,s=new Date(Date.UTC(n,t+1,0)).getUTCDate();return Date.UTC(n,t,Math.min(c,s))};e>0&&a(e)>i&&e--;const r=Math.floor(e/12),l=Math.max(0,(i-a(e))/dayInMilliseconds);s.textContent=[r?r+" 年":"",e%12?e%12+" 个月":"",l+" 天"].filter(Boolean).join(" ")}}updateBlogUptime(),document.addEventListener("kkpt:page",updateBlogUptime)